            "svg": "<rect x=\"30\" y=\"36\" width=\"40\" height=\"8\" rx=\"3\" fill=\"#22c55e\" stroke=\"#14532d\" stroke-width=\"2\"/><path d=\"M 56 42 L 62 58 L 52 58 L 50 42 Z\" fill=\"#16a34a\" stroke=\"#14532d\" stroke-width=\"2\"/>"
          },
          {
