            "svg": "<rect x=\"27\" y=\"64\" width=\"46\" height=\"8\" rx=\"2\" fill=\"#a16207\" stroke=\"#422006\" stroke-width=\"2\"/><rect x=\"45\" y=\"63\" width=\"10\" height=\"10\" rx=\"1.5\" fill=\"#facc15\" stroke=\"#422006\" stroke-width=\"2\"/>"
          }
